"""Matched compile-task timings and byte-equivalence checks; developer controller only."""
from pathlib import Path
import hashlib,json,os,platform,random,statistics,subprocess,time
R=Path(__file__).resolve().parents[1];D=R/'artifacts/codebase-refresh'/('dispatch-'+str(time.time_ns()));D.mkdir(parents=True)
BASE=Path(os.environ['RF2_BASELINE_COMPILER']).resolve();NEW=Path(os.environ['RF2_TEST_COMPILER']).resolve()
trials=int(os.environ.get('RF2_BENCH_TRIALS','21'));assert 3<=trials<=101
runtime=D/'runtime.rf2';runtime.write_text(''.join((R/x).read_text()for x in ['native/rf2.rf2','native/core.rf2','native/attendance.rf2','native/attendance-kernel.rf2','native/fingerprint.rf2','native/invoice.rf2','native/invoice-kernel.rf2','native/prepared.rf2','native/workspace.rf2','native/editor.rf2']))
tasks=[('compiler',R/'native/compiler/compiler.rf2'),('runtime',runtime),('checksum',R/'examples/file-checksum.rf2')];raw=[]
# Baseline and candidate receive identical source, options, output filesystem and PATH.
for name,source in tasks:
 for opt in [False,True]:
  expected=None
  for label,compiler in [('baseline',BASE),('candidate',NEW)]:
   output=D/f'warm-{name}-{opt}-{label}';q=subprocess.run([compiler,source,output,*(['--opt']if opt else[])],capture_output=True,env={'PATH':'/nonexistent'},timeout=30);assert q.returncode==0,q.stderr
   data=output.read_bytes()
   if expected is None:expected=data
   else:assert data==expected,(name,opt,'generated bytes differ')
  for trial in range(trials):
   order=[('baseline',BASE),('candidate',NEW)];random.Random(2600+trial).shuffle(order)
   for label,compiler in order:
    output=D/f'{name}-{opt}-{trial}-{label}';start=time.perf_counter_ns();q=subprocess.run([compiler,source,output,*(['--opt']if opt else[])],capture_output=True,env={'PATH':'/nonexistent'},timeout=30);elapsed=(time.perf_counter_ns()-start)/1e6;assert q.returncode==0 and output.read_bytes()==expected,(name,opt,label)
    raw.append({'task':name,'optimized':opt,'trial':trial,'variant':label,'ms':elapsed});output.unlink()
rows=[]
for name,_ in tasks:
 for opt in [False,True]:
  a=[x['ms']for x in raw if x['task']==name and x['optimized']==opt and x['variant']=='baseline'];b=[x['ms']for x in raw if x['task']==name and x['optimized']==opt and x['variant']=='candidate'];delta=[y-x for x,y in zip(a,b)];rng=random.Random(260026);bs=sorted(statistics.median(rng.choices(delta,k=trials))for _ in range(10000));rows.append({'task':name,'optimized':opt,'baselineMedianMs':statistics.median(a),'candidateMedianMs':statistics.median(b),'candidateMinusBaselinePairedMedianMs':statistics.median(delta),'pairedBootstrap95Ms':[bs[250],bs[9749]]})
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
report={'schema':'rf2.compiler.dispatch.v1','passed':True,'trialsPerTaskMode':trials,'generatedBytesEqual':True,'rows':rows,'raw':raw,'compilerSHA256':{'baseline':sha(BASE),'candidate':sha(NEW)},'sourceSHA256':sha(R/'native/compiler/compiler.rf2'),'controllerSHA256':sha(Path(__file__)),'host':platform.platform(),'limits':'One host, process-inclusive warm filesystem compile/write tasks, no signing. Candidate and baseline compile identical sources. No user application speed, model tokens, energy or cross-host inference.'};(D/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'report':str(D/'report.json'),'rows':rows}))
